import java.io.*;class Student implements Serializable{private static final long serialVersionUID=1L;String name;transient String session="TEMP";Student(String n){name=n;}}public class SerializationDemo{public static void main(String[]x)throws Exception{try(ObjectOutputStream o=new ObjectOutputStream(new FileOutputStream("students.dat"))){o.writeObject(new Student("Asha"));}try(ObjectInputStream i=new ObjectInputStream(new FileInputStream("students.dat"))){Student s=(Student)i.readObject();System.out.println(s.name+", transient="+s.session);}}}
